import {readFileSync,readdirSync} from 'node:fs';
import {gunzipSync} from 'node:zlib';
import type {CalculationSnapshot} from '../../../src/engine/types';

/**
 * Calculation snapshots for the drawing readability tests (sheetReadability.test.ts), stored so the tests need no
 * calculate(): tNN.json.gz the configurator templates (templateProject('tNN'); t09, two cranes, is refreshed alone with
 * NODE_OPTIONS=--max-old-space-size=3072), sNNN.json.gz quick-configurator projects generated by the simulation runs whose sheets had
 * overlapping annotation, cNNN.json.gz sample cases NNN built from their configurator choices (buildProject, listed in
 * scripts/refreshSheetFixtures.ts) whose sheets had overlapping annotation or text on grid bubbles. Each is calculate() of its project (the snapshot's input) without the results the drawings
 * do not read, such as girder-interface and fatigue detail results, the analysis envelope, load combinations, warnings
 * and check notes, each left out only where the drawings stay the same (scripts/refreshSheetFixtures.ts lists them and
 * rebuilds the fixtures from their inputs).
 */
const dir=new URL('./',import.meta.url);
export const sheetFixtureNames=()=>readdirSync(dir).filter(f=>f.endsWith('.json.gz')).map(f=>f.replace('.json.gz','')).sort();
export function sheetFixture(name:string):CalculationSnapshot{
 return JSON.parse(gunzipSync(readFileSync(new URL(`${name}.json.gz`,dir))).toString('utf8'));
}
